create extension if not exists pgcrypto;
create table if not exists leads (id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),first_name text,last_name text,phone_raw text,phone_e164 text,email text,city text,state text,country text not null default 'MX',source text,source_detail text,meta_lead_id text,whatsapp_user_id text,campaign_id text,campaign_name text,adset_id text,adset_name text,ad_id text,ad_name text,product_vertical text not null default 'UNKNOWN',product_interest text,status text not null default 'NEW',score integer not null default 0,score_class text,assigned_advisor text not null default 'Hector Herrera',consent_contact boolean not null default false,last_contact_at timestamptz,next_action_at timestamptz,notes text);
create unique index if not exists leads_meta_lead_id_unique on leads(meta_lead_id) where meta_lead_id is not null;
create index if not exists leads_phone_e164_idx on leads(phone_e164);
create index if not exists leads_email_idx on leads(lower(email));
create table if not exists appointments (id uuid primary key default gen_random_uuid(),lead_id uuid not null references leads(id) on delete cascade,created_at timestamptz not null default now(),status text not null,starts_at timestamptz not null,ends_at timestamptz not null,timezone text not null,calendar_event_id text,meeting_provider text,meeting_url text,confirmation_status text,confirmed_at timestamptz,rescheduled_from uuid references appointments(id),no_show boolean not null default false,meeting_completed boolean not null default false);
create table if not exists conversations (id uuid primary key default gen_random_uuid(),lead_id uuid not null references leads(id) on delete cascade,channel text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references conversations(id) on delete cascade,lead_id uuid not null references leads(id) on delete cascade,created_at timestamptz not null default now(),direction text not null,channel text not null,sender text,body text,provider_message_id text,ai_generated boolean not null default false,metadata jsonb not null default '{}'::jsonb);
create table if not exists processed_events (id uuid primary key default gen_random_uuid(),provider text not null,event_id text not null,created_at timestamptz not null default now(),unique(provider,event_id));
alter table leads enable row level security; alter table appointments enable row level security; alter table conversations enable row level security; alter table messages enable row level security; alter table processed_events enable row level security;
